const suhu = Number(msg.payload.suhu);
const kelembaban = Number(msg.payload.kelembaban);
const timestamp = msg.payload.timestamp || new Date().toISOString();
const received = new Date().toISOString();
const threshold = flow.get('batas_suhu') !== undefined ? Number(flow.get('batas_suhu')) : 30;
const alert = suhu > threshold;

const sensorData = { suhu, kelembaban, timestamp, received, threshold, alert };
flow.set('latest_sensor', sensorData);

const wsMsg = { payload: JSON.stringify(sensorData) };
const dbMsg = {
    topic: 'INSERT INTO history (suhu, kelembaban, timestamp, received) VALUES ($suhu, $kelembaban, $timestamp, $received);',
    payload: {
        $suhu: suhu,
        $kelembaban: kelembaban,
        $timestamp: timestamp,
        $received: received
    }
};
return [wsMsg, dbMsg];

msg.headers = { 'Access-Control-Allow-Origin': '*' };
if (msg.req.headers['x-api-key'] !== 'bima-iot-key-2026') {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return msg;
}
const data = flow.get('latest_sensor') || { suhu: null, kelembaban: null, threshold: flow.get('batas_suhu') ?? 30, alert: false };
msg.payload = { status: 'success', data: data, server_time: new Date().toISOString() };
return msg;

msg.headers = { 'Access-Control-Allow-Origin': '*' };
if (msg.req.headers['x-api-key'] !== 'bima-iot-key-2026') {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return [null, msg];
}
msg.topic = 'SELECT id, suhu, kelembaban, timestamp, received FROM history ORDER BY id DESC LIMIT 15;';
return [msg, null];

const rows = Array.isArray(msg.payload) ? msg.payload.reverse() : [];
msg.payload = { status: 'success', count: rows.length, data: rows };
return msg;

msg.headers = { 'Access-Control-Allow-Origin': '*' };
if (msg.req.headers['x-api-key'] !== 'bima-iot-key-2026') {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return [msg, null];
}
const body = msg.payload || {};
if (!body.device || !body.action) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Parameter device dan action wajib diisi' };
    return [msg, null];
}
const mqttMsg = {
    topic: 'iot/kontrol',
    payload: JSON.stringify({ device: body.device, action: body.action, timestamp: new Date().toISOString() })
};
msg.payload = { status: 'success', message: 'Perintah ' + body.device + ' -> ' + body.action + ' terkirim' };
return [msg, mqttMsg];

msg.headers = { 'Access-Control-Allow-Origin': '*' };
if (msg.req.headers['x-api-key'] !== 'bima-iot-key-2026') {
    msg.statusCode = 401;
    msg.payload = { status: 'error', message: 'Unauthorized: X-API-Key tidak valid' };
    return msg;
}
const val = Number(msg.payload && msg.payload.threshold);
if (isNaN(val)) {
    msg.statusCode = 400;
    msg.payload = { status: 'error', message: 'Nilai threshold harus berupa angka' };
    return msg;
}
flow.set('batas_suhu', val);
msg.payload = { status: 'success', threshold: val, message: 'Batas suhu diatur ke ' + val + ' C' };
return msg;

msg.headers = {
    'Access-Control-Allow-Origin': '*',
    'Access-Control-Allow-Methods': 'GET, POST, PUT, OPTIONS',
    'Access-Control-Allow-Headers': 'Content-Type, X-API-Key'
};
msg.statusCode = 204;
msg.payload = '';
return msg;
